#include <vector>
// Branchy (can mispredict on random data):
long long sumGE_branchy(const std::vector<int>& a, int t){
    long long s = 0;
    for (int x : a) if (x >= t) s += x;
    return s;
}
// Branchless: multiply by the 0/1 comparison result, no data-dependent branch.
long long sumGE_branchless(const std::vector<int>& a, int t){
    long long s = 0;
    for (int x : a) s += (long long)x * (x >= t);
    return s;
}

def sum_ge_branchless(a, t):
    # multiply by the boolean (0/1); no data-dependent branch
    return sum(x * (x >= t) for x in a)
